effect.shader:
void main() {
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
float l = dot(src.rgb, vec3(0.299, 0.587, 0.114));
vec3 graded = src.rgb + (vec3(1.0) - l) * vec3(-0.08, 0.06, 0.10) + l * vec3(0.12, -0.02, -0.10);
graded = mix(src.rgb, graded, clamp(intensity, 0.0, 1.0));
float gl = dot(graded, vec3(0.299, 0.587, 0.114));
graded = mix(vec3(gl), graded, clamp(saturation, 0.0, 2.0));
gl_FragColor = vec4(clamp(graded, vec3(0.0), vec3(1.0)), src.a);
}
